begin;

do $$
declare
  v_sector uuid; v_family uuid; v_recovery uuid; v_treatment uuid; v_id uuid; v_text text;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_family from public.categories where slug='addiction-family-support' and sector_id=v_sector;
  select id into v_recovery from public.categories where slug='addiction-recovery-core' and sector_id=v_sector;
  select id into v_treatment from public.categories where slug='addiction-treatment-care' and sector_id=v_sector;
  if v_sector is null or v_family is null or v_recovery is null or v_treatment is null then raise exception 'addiction family recovery taxonomy missing'; end if;
  select id into v_id from public.content where slug='addiction-family-recovery-caregiver-wellbeing' and status='draft';
  if v_id is null then raise exception 'family recovery draft missing or already published'; end if;
  select string_agg(txt,E'\n\n' order by ord) into v_text from (
    select ord, case
      when block->>'type' in ('paragraph','heading') then block->>'text'
      when block->>'type'='list' then (select string_agg(value,E'\n') from jsonb_array_elements_text(block->'items'))
      when block->>'type'='faq' then (select string_agg((item->>'question')||' '||(item->>'answer'),E'\n') from jsonb_array_elements(block->'items') item)
      else null end txt
    from public.content c, jsonb_array_elements(c.body_json->'blocks') with ordinality b(block,ord) where c.id=v_id
  ) s where txt is not null and btrim(txt)<>'';
  update public.content set
    body_text=v_text, sector_id=v_sector, category_id=v_family, content_type='article',
    seo_title='تعافي الأسرة بعد الإدمان | روافد', seo_description='مرجع عربي لتعافي الأسرة بعد الإدمان: استعادة الأدوار والثقة، صحة مقدم الرعاية، حماية الأطفال، العلاج الأسري، CRAFT، وخطة عملية لثلاثين وتسعين يومًا بأمان.', canonical_url='/content/addiction-family-recovery-caregiver-wellbeing/',
    robots_index=true, robots_follow=true, search_aliases=array['تعافي الأسرة بعد الإدمان','دور الأسرة في علاج الإدمان','صحة مقدم الرعاية','استعادة الثقة بعد الإدمان','family recovery addiction','caregiver wellbeing addiction','CRAFT addiction family'],
    primary_keyword='تعافي الأسرة بعد الإدمان', secondary_keywords=array['دور الأسرة في علاج الإدمان','الثقة بعد الإدمان','صحة مقدم الرعاية','العلاج الأسري للإدمان','CRAFT','أطفال المدمن','دعم أسرة المتعافي','الانتكاس والأسرة'],
    semantic_terms=array['تعافي الأسرة','مقدم الرعاية','العلاج الأسري','العلاج الزوجي','الخصوصية','الموافقة','CRAFT','الأطفال','الحدود','إعادة بناء الثقة','العبء الأسري','الرعاية المستمرة','الأدوار الأسرية','التكيف'],
    search_intent='informational', references_json='[{"url":"https://library.samhsa.gov/sites/default/files/tip-39-treatment-family-therapy-pep20-02-02-012.pdf","year":2020,"title":"TIP 39: Substance Use Disorder Treatment and Family Therapy","publisher":"SAMHSA","source_type":"guideline","authority_tier":"primary"},{"url":"https://www.samhsa.gov/mental-health/children-and-families/coping-resources","year":2026,"title":"Helping Families Cope with Mental Health and Substance Use Disorders","publisher":"SAMHSA","source_type":"official-definition","authority_tier":"primary"},{"url":"https://www.who.int/publications/i/item/international-standards-for-the-treatment-of-drug-use-disorders","year":2020,"title":"International Standards for the Treatment of Drug Use Disorders","publisher":"WHO and UNODC","source_type":"guideline","authority_tier":"primary"},{"url":"https://pubmed.ncbi.nlm.nih.gov/41970367/","year":2026,"title":"Efficacy of Family-based Interventions in Addressing Substance Use Disorders: A Systematic Review on Randomized Controlled Trials","publisher":"PubMed / Current Addiction Reports","source_type":"systematic-review","authority_tier":"primary"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36744608/","year":2023,"title":"The effectiveness of psychosocial interventions for family members impacted by another''s substance use: A systematic review and meta-analysis","publisher":"PubMed / Drug and Alcohol Review","source_type":"systematic-review","authority_tier":"primary"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31770469/","year":2020,"title":"Community reinforcement and family training and rates of treatment entry: a systematic review","publisher":"PubMed / Addiction","source_type":"systematic-review","authority_tier":"primary"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36564902/","year":2023,"title":"Effects of family therapy for substance abuse: A systematic review of recent research","publisher":"PubMed / Family Process","source_type":"systematic-review","authority_tier":"primary"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36716584/","year":2023,"title":"Effective behaviour change techniques for family and close friends: A systematic review and meta-analysis across the addictions","publisher":"PubMed / Clinical Psychology Review","source_type":"systematic-review","authority_tier":"primary"},{"url":"https://www.nice.org.uk/guidance/cg51","year":2016,"title":"Drug misuse in over 16s: psychosocial interventions","publisher":"NICE","source_type":"guideline","authority_tier":"primary"}]'::jsonb, schema_json='{"content_contract_version":6,"disclaimer_url":"/disclaimer","disclaimer_label":"إخلاء المسؤولية والتنبيهات","taxonomy_reviewed":true,"classification_confidence":0.99,"classification_rationale":"هذه الصفحة تنتمي أساسًا إلى مسار الأسرة ومقدمي الرعاية داخل قطاع الإدمان والتعافي لأنها تعالج تعافي الأسرة كنظام مستقل، وإعادة الأدوار والثقة وصحة مقدم الرعاية والأطفال والخصوصية والعلاج الأسري وقياس نتائج الأسرة، وتعمل كصفحة مظلة تربط الأدلة المتخصصة دون تكرارها.","rewrite_method":"evidence-led-rewrite","originality_report":{"passed":true,"method":"manual-evidence-structure-and-duplication-review","duplicate_page_created":false},"strategic_scientific_value":"high","uniqueness_rationale":"تختلف هذه الصفحة عن أدلة الحدود والمال والطفل والانتكاس الموجودة لأنها لا تعيد إجراءاتها، بل تبني نموذجًا متكاملًا لتعافي الأسرة بعد الإدمان يربط الأدوار والثقة والخصوصية وصحة مقدم الرعاية والعمل والسكن ونتائج الأسرة وخطة الثلاثين والتسعين يومًا ضمن مسار قرار واحد قابل للمتابعة.","page_mechanism":{"purpose":"تحويل تعافي الأسرة من مفهوم عام إلى مسار عملي قائم على الأدلة له أهداف وحدود ومؤشرات وقرارات مستقلة عن مسار المريض.","audience":"الأسر والشركاء ومقدمو الرعاية والمختصون ومديرو البرامج الذين يحتاجون خريطة عملية لإعادة بناء الحياة الأسرية بعد اضطراب استخدام المواد.","interaction_model":"ينتقل القارئ من خريطة الأثر والسلامة إلى الأدوار والثقة والتواصل وصحة مقدم الرعاية ثم يختار مؤشرات وخطة ثلاثين وتسعين يومًا.","content_model":"صفحة ركيزة مرجعية تجمع الأدلة الأسرية والخصوصية وCRAFT والأطفال والعبء والنتائج وتربط بالصفحات الإجرائية المتخصصة بدل نسخها."},"search_intent_questions":["كيف تتعافى الأسرة بعد الإدمان؟","كيف تعود الثقة بعد الإدمان؟","كيف أتعامل مع شخص متعافٍ من الإدمان؟","ما دور الأسرة في علاج الإدمان؟","هل العلاج الأسري مفيد للإدمان؟","كيف أحمي نفسي كمقدم رعاية؟","ماذا أقول للأطفال عن إدمان أحد الوالدين؟","ماذا أفعل إذا رفض المدمن العلاج؟","ما هو CRAFT للأسرة؟","كيف تتصرف الأسرة عند عودة الاستخدام؟"],"claim_source_map":[{"claim":"اضطراب استخدام المواد يؤثر في نظام الأسرة ويمكن أن يكون دمج الأسرة جزءًا مهمًا من العلاج","sources":["SAMHSA TIP 39 2020","WHO-UNODC Treatment Standards 2020"]},{"claim":"التدخلات الأسرية قد تقلل استخدام المواد وتحسن أداء الأسرة في عدد من التجارب","sources":["Family-based Interventions Systematic Review 2026","Family Therapy Systematic Review 2023"]},{"claim":"التدخلات النفسية الاجتماعية الموجهة لأفراد الأسرة قد تحسن بعض مؤشرات الضيق والتكيف","sources":["Affected Family Members Systematic Review and Meta-analysis 2023"]},{"claim":"العلاج الأسري يحتاج سياسات واضحة للموافقة والخصوصية وحدود الإفصاح","sources":["SAMHSA TIP 39 2020"]},{"claim":"يمكن أن تكون التدخلات الأسرية والزوجية من الأساليب النفسية الاجتماعية المفيدة في سياقات مناسبة","sources":["WHO-UNODC Treatment Standards 2020","NICE CG51"]},{"claim":"CRAFT تدخل منظم يمكنه زيادة الارتباط بالعلاج لدى بعض الرافضين مع تفاوت النتائج بحسب التنفيذ والسياق","sources":["CRAFT Systematic Review 2020"]},{"claim":"أفراد الأسرة المتأثرون باستخدام قريب للمواد قد يحتاجون تدخلًا يستهدف صحتهم هم وليس سلوك المريض فقط","sources":["Affected Family Members Systematic Review and Meta-analysis 2023","SAMHSA Families Coping 2026"]},{"claim":"العمل مع الأسرة ينبغي أن يكون ملائمًا للعمر والسياق ولا يحل محل تقييم السلامة والاحتياجات الفردية","sources":["SAMHSA TIP 39 2020","WHO-UNODC Treatment Standards 2020"]},{"claim":"الأساليب السلوكية الموجهة للأسرة والأصدقاء تختلف في مكوناتها وفعاليتها ويجب عدم اختزالها في نصائح عامة","sources":["Behaviour Change Techniques Meta-analysis 2023"]}],"source_versions_reviewed":["SAMHSA TIP 39 2020","SAMHSA Families Coping updated 2026","WHO-UNODC Treatment Standards 2020","Family-based Interventions Systematic Review 2026","Affected Family Members Systematic Review and Meta-analysis 2023","CRAFT Systematic Review 2020","Family Therapy Systematic Review 2023","Behaviour Change Techniques Meta-analysis 2023","NICE CG51"]}'::jsonb,
    author_display_name='فريق تحرير منصة روافد', reviewer_display_name=null, reviewer_credentials=null, last_reviewed_at=now(), medical_disclaimer=null,
    status='published', published_at=now(), updated_at=now() where id=v_id;
  insert into public.content_categories(content_id,category_id,is_primary) values (v_id,v_family,true),(v_id,v_recovery,false),(v_id,v_treatment,false)
  on conflict (content_id,category_id) do update set is_primary=excluded.is_primary;
  update public.content_categories set is_primary=false where content_id=v_id and category_id<>v_family;
  update public.content_categories set is_primary=true where content_id=v_id and category_id=v_family;
end $$;

commit;
